#!/bin/bash
set -euo pipefail
WEB=/var/www/fusionpbx/app/agent_dashboard
B64=''
echo "$B64" | base64 -d > /tmp/skykin_config.php
docker cp /tmp/skykin_config.php skykin-web:$WEB/skykin_config.php
docker exec skykin-web php -r 'opcache_reset();' 2>/dev/null || true
docker exec skykin-web php -r '
require "/var/www/fusionpbx/app/agent_dashboard/skykin_config.php";
$a=["direction"=>"inbound","billsec"=>65,"duration"=>70,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198037","caller_id_number"=>"+251911813131","start_epoch"=>1000,"last_arg"=>"user/203@ahununu","cc_agent_bridged"=>"/203@ahununu"];
$b=["direction"=>"inbound","billsec"=>7,"duration"=>10,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198038","caller_id_number"=>"+251911813131","start_epoch"=>1002,"last_arg"=>"user/202@ahununu","cc_agent_bridged"=>"/202@ahununu"];
$c=skykin_cdr_collapse_hunt_legs([$a,$b]);
echo "dup_answered=", count($c), " billsec=", (int)$c[0]["billsec"], " label=", skykin_cdr_result_label($c[0]), "\n";
$m1=["direction"=>"inbound","billsec"=>2,"duration"=>5,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198036","caller_id_number"=>"+251911528271","start_epoch"=>2000,"last_arg"=>"","cc_agent_bridged"=>""];
$m2=["direction"=>"inbound","billsec"=>2,"duration"=>5,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198037","caller_id_number"=>"+251911528271","start_epoch"=>2001,"last_arg"=>"","cc_agent_bridged"=>""];
$m3=["direction"=>"inbound","billsec"=>0,"duration"=>1,"hangup_cause"=>"CALL_REJECTED","destination_number"=>"+251116198038","caller_id_number"=>"+251911528271","start_epoch"=>2002,"last_arg"=>"","cc_agent_bridged"=>""];
$c2=skykin_cdr_collapse_hunt_legs([$m1,$m2,$m3]);
echo "dup_missed=", count($c2), " label=", skykin_cdr_result_label($c2[0]), "\n";
'
echo DONE
